// TestRunnerRequestBudgetNudgesPostChildRereadsButDoesNotBlock locks
// in the no-bandaid memory: post-child reread used to nudge on the
// first revisit and HARD-BLOCK on the second. The block fired
// prematurely on mutation parents that legitimately re-read the
// same file at different ranges to verify multiple anchors (see
// #101's wedge chain). doom_loop_guard catches exact-duplicate
// reads; MaxToolSteps caps total budget; completion_gate enforces
// mutation closure. The nudge stays as a soft signal but the hard
// block was removed.
func TestRunnerRequestBudgetNudgesPostChildRereadsButDoesNotBlock(t *testing.T) {
	state := newRunnerRequestBudgetState(4)

	state.readOnlyChildTaskSatisfied = true
	state.noteReadOnlyChildPacket([]string{"internal/runtime/agent/discovery_redirect.go"})

	req := workspace.ToolRequest{Tool: "read_file", Path: "internal/runtime/agent/discovery_redirect.go"}

	state.noteReadClassRequest(req)

	decision := state.explorationDecision(&Runner{}, req, nil)
	if !decision.Handled || decision.Nudge == "" || decision.EventRole != "post_child_reread_nudge" {
		t.Fatalf("expected first post-child reread to nudge, got %#v", decision)
	}

	state.noteReadClassRequest(req)

	decision = state.explorationDecision(&Runner{}, req, nil)
	if decision.Handled {
		t.Fatalf("expected repeated post-child reread to be allowed (no hard block); got %#v", decision)
	}

	if decision.RejectStopReason != "" {
		t.Fatalf("expected no stop reason on repeated post-child reread, got %q", decision.RejectStopReason)
	}
}

// TestWriteReadyNudgeActiveDefersRejectionRetry verifies that when
// writeReadyNudgeActive is true, a rejection retry returns a nudge
// instead of force-answering, deferring to the write-ready escalation.
func TestWriteReadyNudgeActiveDefersRejectionRetry(t *testing.T) {
	state := newRunnerRequestBudgetState(2)

	state.writeReadyNudgeActive = true

	req := workspace.ToolRequest{Tool: "search_content", Path: "internal/surfaces/tui/app"}
	fingerprint := "search_content|internal/surfaces/tui/app"

	state.fingerprint.rejected[fingerprint] = "Chained search rejected"
	state.fingerprint.rejectedRetries = make(map[string]int)

	decision := state.loopPolicy.EvaluateFingerprint(&state, RunPolicy{}, req, fingerprint)
	if !decision.Handled {
		t.Fatal("expected rejection retry to be handled")
	}
	assertLoopPolicyDecision(t, decision, autonomy.PolicyObserve, "rejection_retry_deferred_to_write_ready")

	if decision.ForceAnswerReason != "" {
		t.Fatalf("expected nudge (not force-answer) when writeReadyNudgeActive, got ForceAnswerReason=%q", decision.ForceAnswerReason)
	}

	if decision.EventRole != "rejection_retry_deferred_to_write_ready" {
		t.Fatalf("expected rejection_retry_deferred_to_write_ready event, got %q", decision.EventRole)
	}

	if decision.Nudge == "" {
		t.Fatal("expected a nudge message when writeReadyNudgeActive is true")
	}

	t.Logf("nudge: %s", decision.Nudge)
}

// TestRejectionRetryNudgeThenBlock verifies the nudge-then-block pattern:
// first retry of a rejected fingerprint gets a nudge, second gets force-answered.
func TestRejectionRetryNudgeThenBlock(t *testing.T) {
	state := newRunnerRequestBudgetState(2)
	req := workspace.ToolRequest{Tool: "list_files", Path: "."}
	fingerprint := "list_files|."

	state.fingerprint.rejected[fingerprint] = "Broad inspection blocked"
	state.fingerprint.rejectedRetries = make(map[string]int)

	// First retry: nudge
	d1 := state.loopPolicy.EvaluateFingerprint(&state, RunPolicy{}, req, fingerprint)
	if !d1.Handled || d1.Nudge == "" {
		t.Fatalf("expected nudge on first retry, got %#v", d1)
	}
	assertLoopPolicyDecision(t, d1, autonomy.PolicyObserve, "rejection_retry_nudge")

	if d1.ForceAnswerReason != "" {
		t.Fatalf("expected nudge (not force-answer) on first retry, got ForceAnswerReason=%q", d1.ForceAnswerReason)
	}

	t.Log("first retry: nudge")

	// Second retry: blocked
	d2 := state.loopPolicy.EvaluateFingerprint(&state, RunPolicy{}, req, fingerprint)
	if !d2.Handled || d2.ForceAnswerReason != "rejection_retry_blocked" {
		t.Fatalf("expected force-answer on second retry, got %#v", d2)
	}
	assertLoopPolicyDecision(t, d2, autonomy.PolicyStop, "rejection_retry_blocked")

	t.Log("second retry: blocked")
}

// TestNoteWriteProgressClearsWriteReadyNudgeAndRejectionState verifies
// that noteWriteProgress clears writeReadyNudgeActive and both
// rejected/rejectedRetries maps.
func TestNoteWriteProgressClearsWriteReadyNudgeAndRejectionState(t *testing.T) {
	state := newRunnerRequestBudgetState(2)

	state.writeReadyNudgeActive = true
	state.fingerprint.rejected["fp"] = "test rejection"
	state.fingerprint.rejectedRetries = map[string]int{"fp": 3}

	state.noteWriteProgress()

	if state.writeReadyNudgeActive {
		t.Fatal("writeReadyNudgeActive should be false after noteWriteProgress")
	}

	if _, ok := state.fingerprint.rejected["fp"]; ok {
		t.Fatal("rejected fingerprints should be cleared after noteWriteProgress")
	}

	if _, ok := state.fingerprint.rejectedRetries["fp"]; ok {
		t.Fatal("rejectedRetries should be cleared after noteWriteProgress")
	}
}

func assertLoopPolicyDecision(t *testing.T, decision runnerRequestBudgetDecision, wantDecision autonomy.ToolPolicyDecision, wantReason string) {
	t.Helper()

	if decision.Policy.ContractID != autonomy.ContractPackLoopRepeatedCall {
		t.Fatalf("expected loop contract pack %q, got %#v", autonomy.ContractPackLoopRepeatedCall, decision.Policy)
	}
	if decision.Policy.InvariantID != loopPolicyInvariantRepeatedCall {
		t.Fatalf("expected invariant %q, got %#v", loopPolicyInvariantRepeatedCall, decision.Policy)
	}
	if decision.Policy.Decision != wantDecision {
		t.Fatalf("expected policy decision %q, got %#v", wantDecision, decision.Policy)
	}
	if decision.Policy.ReasonCode != wantReason {
		t.Fatalf("expected reason %q, got %#v", wantReason, decision.Policy)
	}
}

// TestRewriteReadFileForPlannedNewFileFiresOnRequiredPath verifies
// the Phase 7.3 / harness-fix-#7 contract: a "no such file" error
// on a read targeting a required_edit_path becomes an actionable
// nudge naming the whole-file shape on submit_plan, NOT a bare
// "file not found" the planner treats as a blocker.
func TestRewriteReadFileForPlannedNewFileFiresOnRequiredPath(t *testing.T) {
	req := workspace.ToolRequest{Tool: "read_file", Path: "cmd/idiom/init.go"}
	result := workspace.ToolResult{Tool: "read_file", Error: "no such file or directory"}
	brief := workerruntime.WorkerRuntimeBrief{
		RequiredEditPaths: []string{"cmd/idiom/init.go", "cmd/idiom/main.go"},
	}
	got := rewriteMissingRequiredNewFileProbe(req, result, brief)

	if !strings.Contains(got.Error, "NEW FILE") {
		t.Fatalf("rewrite should call out the new-file shape; got: %s", got.Error)
	}

	if !strings.Contains(got.Error, "replace_all") {
		t.Fatalf("rewrite should mention replace_all; got: %s", got.Error)
	}

	if !strings.Contains(got.Error, "submit_plan") {
		t.Fatalf("rewrite should point at submit_plan; got: %s", got.Error)
	}

	if !strings.Contains(got.Error, "missing body evidence") {
		t.Fatalf("rewrite should point at the new-file body evidence contract; got: %s", got.Error)
	}
}

// TestRewriteReadFileForPlannedNewFileLeavesUnrelatedErrorsAlone
// verifies the gate's selectivity: errors on paths NOT in
// required_edit_paths pass through unchanged so the planner sees
// the original "did-you-mean" diagnostics.
func TestRewriteReadFileForPlannedNewFileLeavesUnrelatedErrorsAlone(t *testing.T) {
	req := workspace.ToolRequest{Tool: "read_file", Path: "some/other/path.go"}
	original := workspace.ToolResult{Tool: "read_file", Error: "no such file"}
	brief := workerruntime.WorkerRuntimeBrief{
		RequiredEditPaths: []string{"cmd/idiom/init.go"},
	}
	got := rewriteMissingRequiredNewFileProbe(req, original, brief)

	if got.Error != original.Error {
		t.Fatalf("error on unrelated path should pass through; got rewrite: %s", got.Error)
	}
}

func TestRewriteMissingRequiredNewFileProbeFiresOnMissingParentOutline(t *testing.T) {
	req := workspace.ToolRequest{Tool: "go_file_outline", Path: "./internal/contracts/writerroute"}
	original := workspace.ToolResult{Tool: "go_file_outline", Error: "open /repo/internal/contracts/writerroute: no such file or directory"}
	brief := workerruntime.WorkerRuntimeBrief{
		RequiredEditPaths: []string{
			"internal/contracts/writerroute/decision.go",
			"internal/contracts/writerroute/decision_test.go",
			"internal/surfaces/tui/app/writer_route.go",
		},
	}
	got := rewriteMissingRequiredNewFileProbe(req, original, brief)

	for _, want := range []string{
		"Required new-file directory does not exist yet",
		"internal/contracts/writerroute/decision.go",
		"internal/contracts/writerroute/decision_test.go",
		"submit_plan",
		"replace_all",
		"Do NOT keep trying to inspect",
	} {
		if !strings.Contains(got.Summary+"\n"+got.Error, want) {
			t.Fatalf("rewritten result missing %q:\n%#v", want, got)
		}
	}

	if strings.Contains(got.Error, "internal/surfaces/tui/app/writer_route.go") {
		t.Fatalf("rewrite should only list required paths under the missing probe target, got: %s", got.Error)
	}
}

