func TestRunnerDeepSeekInvalidFinalRetryPreservesReasoningContentInHistory(t *testing.T) {
	t.Setenv("DEEPSEEK_API_KEY", "test-key")
	root := t.TempDir()

	var payloads []emptyReplyRetryRequestPayload
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var payload emptyReplyRetryRequestPayload
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			t.Fatalf("decode request: %v", err)
		}

		payloads = append(payloads, payload)
		if len(payloads) > 1 {
			t.Fatalf("unexpected extra chat request")
		}

		_, _ = w.Write([]byte(`{"choices":[{"message":{"role":"assistant","content":"Done."}}]}`))
	}))
	defer server.Close()

	thinkingOff := false
	runner := &Runner{
		Client: llama.NewClient(server.URL, time.Second).WithBackend(config.BackendDeepSeek),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxToolSteps: 1, MaxNoProgressTurns: 2},
	}

	answer, ok, err := runner.retryInvalidFinalAnswer(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "answer"}},
		llama.ChatMessage{
			Role:             "assistant",
			Content:          "```tool\n{\"tool\":\"read_file\",\"path\":\"README.md\"}\n```",
			ReasoningContent: "invalid final reasoning",
		},
		llama.ChatOptions{Model: "deepseek-v4-flash", EnableThinking: &thinkingOff, PreserveThinking: false, MaxTokens: 128},
		nil,
		nil,
		"textual tool call",
	)
	if err != nil {
		t.Fatalf("retryInvalidFinalAnswer: %v", err)
	}
	if !ok || answer != "Done." {
		t.Fatalf("unexpected retry result ok=%v answer=%q", ok, answer)
	}
	if len(payloads) != 1 {
		t.Fatalf("expected one model request, got %d", len(payloads))
	}
	if got := payloads[0].Thinking["type"]; got != "disabled" {
		t.Fatalf("DeepSeek invalid-final retry should disable new thinking, got thinking=%#v", payloads[0].Thinking)
	}

	var foundReasoning bool
	for _, message := range payloads[0].Messages {
		if message.Role == "assistant" && message.ReasoningContent == "invalid final reasoning" {
			foundReasoning = true
		}
		if message.Role != "assistant" && message.ReasoningContent != "" {
			t.Fatalf("DeepSeek retry should not send non-assistant reasoning_content, got %#v", payloads[0].Messages)
		}
	}
	if !foundReasoning {
		t.Fatalf("DeepSeek invalid-final retry should preserve prior assistant reasoning_content, got %#v", payloads[0].Messages)
	}
}

type emptyReplyRetryRequestPayload struct {
	Messages           []llama.ChatMessage `json:"messages"`
	Thinking           map[string]string   `json:"thinking,omitempty"`
	ChatTemplateKwargs *struct {
		EnableThinking *bool `json:"enable_thinking"`
		Preserve       bool  `json:"preserve_thinking"`
	} `json:"chat_template_kwargs,omitempty"`
}

func runEmptyReplyRetry(t *testing.T, backend string, opts llama.ChatOptions) []emptyReplyRetryRequestPayload {
	t.Helper()

	root := t.TempDir()
	var payloads []emptyReplyRetryRequestPayload
	replies := []string{
		`{"choices":[{"message":{"role":"assistant","reasoning_content":"unfinished reasoning","content":""}}]}`,
		`{"choices":[{"message":{"role":"assistant","content":"Done."}}]}`,
	}

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var payload emptyReplyRetryRequestPayload
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			t.Fatalf("decode request: %v", err)
		}

		payloads = append(payloads, payload)
		if len(payloads) > len(replies) {
			t.Fatalf("unexpected extra chat request")
		}

		_, _ = w.Write([]byte(replies[len(payloads)-1]))
	}))
	defer server.Close()

	client := llama.NewClient(server.URL, time.Second)
	if strings.TrimSpace(backend) != "" {
		client = client.WithBackend(backend)
	}

	runner := &Runner{
		Client: client,
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxToolSteps: 1, MaxNoProgressTurns: 2},
	}

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "answer"}},
		opts,
		nil,
		nil,
		nil,
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	if answer != "Done." {
		t.Fatalf("unexpected answer %q", answer)
	}
	if len(payloads) != 2 {
		t.Fatalf("expected two model requests, got %d", len(payloads))
	}

	return payloads
}

func writeTestFile(root string, path string, content string) error {
	fullPath := filepath.Join(root, path)
	if err := os.MkdirAll(filepath.Dir(fullPath), 0o755); err != nil {
		return err
	}

	return os.WriteFile(fullPath, []byte(content), 0o644)
}

func TestRunnerExecutesReadOnlyChildTask(t *testing.T) {
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "route evidence\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	replies := []string{
		"```tool\n{\"tool\":\"task\",\"agent\":\"explorer\",\"mode\":\"read_only\",\"prompt\":\"inspect README\"}\n```",
		"Child evidence: README.md mentions route evidence.",
		"Final: child evidence found in README.md.",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests >= len(replies) {
			t.Fatalf("unexpected extra chat request")
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	runner := &Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxToolSteps: 3, MaxNoProgressTurns: 2},
	}

	var sawTask bool

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "delegate focused inspection"}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			if event.Result.Tool == "task" && strings.Contains(event.Result.Output, "Child evidence") {
				sawTask = true
			}
		},
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	if !sawTask {
		t.Fatal("expected task tool result with child output")
	}

	if !strings.Contains(answer, "Final") {
		t.Fatalf("unexpected answer: %q", answer)
	}
}

func TestReadOnlyChildTaskPermissionPolicyDeniesWritesAndAllowsReads(t *testing.T) {
	policy := readOnlyChildTaskPermissionPolicy()
	if decision := policy.Decide(workspace.ToolRequest{Tool: "edit_file", Path: "README.md"}); decision.Decision != PermissionDeny {
		t.Fatalf("edit_file decision = %q, want deny", decision.Decision)
	}

	if decision := policy.Decide(workspace.ToolRequest{Tool: "read_file", Path: "README.md"}); decision.Decision != PermissionAllow {
		t.Fatalf("read_file decision = %q, want allow", decision.Decision)
	}

	if decision := policy.Decide(workspace.ToolRequest{Tool: "task", Prompt: "nested"}); decision.Decision != PermissionDeny {
		t.Fatalf("task decision = %q, want deny", decision.Decision)
	}
}

