func TestPresentableFallbackCandidatePreservesChildDelegatedPacket(t *testing.T) {
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:        "delegated_read_only",
		Contract:          "grounded_evidence",
		Objective:         "Explain how this harness uses child agents.",
		PermissionProfile: "read_only_workspace",
	}
	results := []workspace.ToolResult{{
		Tool:    "read_file",
		Summary: "Read internal/runtime/agent/implementation_flow.go lines 1-80",
		Output:  "package agent\nfunc runChildTask() {}\n",
	}}
	childAnswer := "The answer is grounded in `internal/runtime/agent/implementation_flow.go`.\n\nWhat this establishes:\n- The child runner returns a delegated evidence packet to the parent after bounded read-only inspection."

	answer, ok := presentableFallbackCandidate("child:explorer", brief, results, childAnswer)
	if !ok {
		t.Fatal("expected child delegated fallback packet to remain presentable")
	}

	if answer != childAnswer {
		t.Fatalf("expected child delegated fallback packet to be preserved, got:\n%s", answer)
	}

	for _, forbidden := range []string{"not enough supported evidence", "<<QUESTION>>", "concrete user-facing finding"} {
		if strings.Contains(strings.ToLower(answer), strings.ToLower(forbidden)) {
			t.Fatalf("child delegated fallback should not be rewritten as main-lane uncertainty %q:\n%s", forbidden, answer)
		}
	}
}

type closureDecisionSpyEvidenceEngine struct {
	EvidenceEngine
	closureCalls       int
	answerabilityCalls int
}

func (e *closureDecisionSpyEvidenceEngine) ClosureDecision(brief workerruntime.WorkerRuntimeBrief, results []workspace.ToolResult) ReadOnlyCloseout {
	e.closureCalls++
	return newEvidenceEngine().ClosureDecision(brief, results)
}

func (e *closureDecisionSpyEvidenceEngine) Answerability(brief workerruntime.WorkerRuntimeBrief, results []workspace.ToolResult) readOnlyAnswerabilityLedger {
	e.answerabilityCalls++
	return newEvidenceEngine().Answerability(brief, results)
}

