func TestRunnerExecutesWorkbranchWriteChildTaskWithoutMutatingParent(t *testing.T) {
	root := t.TempDir()
	runGit(t, root, "init")
	runGit(t, root, "config", "user.email", "test@example.com")
	runGit(t, root, "config", "user.name", "Test User")

	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	runGit(t, root, "add", "README.md")
	runGit(t, root, "commit", "-m", "init")

	replies := []string{
		"```tool\n{\"tool\":\"task\",\"agent\":\"patch-readme\",\"mode\":\"workbranch_write\",\"prompt\":\"change README greeting\"}\n```",
		"```tool\n{\"tool\":\"task_ledger\",\"todos\":[{\"id\":\"edit\",\"content\":\"Edit README\",\"status\":\"completed\"},{\"id\":\"verify\",\"content\":\"Check diff\",\"status\":\"completed\"}]}\n```",
		"```tool\n{\"tool\":\"read_file\",\"path\":\"README.md\"}\n```",
		"```tool\n{\"tool\":\"edit_file\",\"path\":\"README.md\",\"start_line\":1,\"end_line\":1,\"content\":\"hello from child\\n\",\"description\":\"replace greeting with child-authored version\"}\n```",
		"Changed files:\n- README.md\nVerification: inspected diff\nConfidence: medium",
		"Parent inspected child patch.",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests >= len(replies) {
			t.Fatalf("unexpected extra chat request")
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	runner := &Runner{
		Client: llama.NewClient(server.URL, 2*time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxToolSteps: 3, MaxNoProgressTurns: 3},
	}

	var childPatch string

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "delegate isolated write"}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			if event.Result.Tool == "task" {
				childPatch = event.Result.Output
			}
		},
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	if answer != "Parent inspected child patch." {
		t.Fatalf("unexpected answer: %q", answer)
	}

	data, err := os.ReadFile(filepath.Join(root, "README.md"))
	if err != nil {
		t.Fatalf("read parent README: %v", err)
	}

	if string(data) != "hello\n" {
		t.Fatalf("parent workspace was mutated: %q", data)
	}

	if !strings.Contains(childPatch, "README.md") || !strings.Contains(childPatch, "hello from child") {
		t.Fatalf("expected child patch output, got:\n%s", childPatch)
	}
}

func TestWorkbranchManagerFallsBackToFilesystemCopyForNonGitWorkspace(t *testing.T) {
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	manager := WorkbranchManager{Root: root}
	checkout, err := manager.Create(context.Background(), "patch-readme")
	if err != nil {
		t.Fatalf("create fallback checkout: %v", err)
	}
	removed := false
	defer func() {
		if removed {
			return
		}
		if err := manager.Remove(context.Background(), checkout); err != nil {
			t.Fatalf("remove fallback checkout: %v", err)
		}
	}()

	if checkout.Mode != "filesystem-copy" || checkout.BaseSHA != "non-git" {
		t.Fatalf("unexpected fallback checkout: %#v", checkout)
	}

	if err := os.WriteFile(filepath.Join(checkout.Path, "README.md"), []byte("hello from non-git child\n"), 0o644); err != nil {
		t.Fatalf("edit checkout file: %v", err)
	}

	diff, err := manager.Diff(context.Background(), checkout)
	if err != nil {
		t.Fatalf("diff fallback checkout: %v", err)
	}
	if !slices.Equal(diff.ChangedPaths, []string{"README.md"}) {
		t.Fatalf("changed paths = %#v, want README.md", diff.ChangedPaths)
	}
	if !strings.Contains(diff.Patch, "hello from non-git child") {
		t.Fatalf("expected fallback patch to include child content, got:\n%s", diff.Patch)
	}

	parentData, err := os.ReadFile(filepath.Join(root, "README.md"))
	if err != nil {
		t.Fatalf("read parent README: %v", err)
	}
	if string(parentData) != "hello\n" {
		t.Fatalf("parent workspace was mutated: %q", parentData)
	}

	if err := manager.Remove(context.Background(), checkout); err != nil {
		t.Fatalf("remove fallback checkout: %v", err)
	}
	removed = true
	checkoutPath := checkout.Path
	if _, err := os.Stat(checkoutPath); !os.IsNotExist(err) {
		t.Fatalf("fallback checkout should be removed, stat err=%v", err)
	}
}

func TestRunnerRoutesWorkbranchChildOntoImplementerClient(t *testing.T) {
	root := t.TempDir()
	runGit(t, root, "init")
	runGit(t, root, "config", "user.email", "test@example.com")
	runGit(t, root, "config", "user.name", "Test User")

	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	runGit(t, root, "add", "README.md")
	runGit(t, root, "commit", "-m", "init")

	// Planner replies: delegate, then final summary after child returns.
	plannerReplies := []string{
		"```tool\n{\"tool\":\"task\",\"agent\":\"patch-readme\",\"mode\":\"workbranch_write\",\"prompt\":\"change greeting\"}\n```",
		"Parent inspected child patch.",
	}
	plannerHits := 0
	plannerServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if plannerHits >= len(plannerReplies) {
			t.Fatalf("planner received unexpected extra request")
		}

		reply := plannerReplies[plannerHits]
		plannerHits++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{"message": map[string]string{"content": reply}}},
		})
	}))

	defer plannerServer.Close()

	// Implementer replies: drive the child through ledger, read, edit, final.
	implReplies := []string{
		"```tool\n{\"tool\":\"task_ledger\",\"todos\":[{\"id\":\"edit\",\"content\":\"Edit README\",\"status\":\"completed\"},{\"id\":\"verify\",\"content\":\"Check diff\",\"status\":\"completed\"}]}\n```",
		"```tool\n{\"tool\":\"read_file\",\"path\":\"README.md\"}\n```",
		"```tool\n{\"tool\":\"edit_file\",\"path\":\"README.md\",\"start_line\":1,\"end_line\":1,\"content\":\"hello from child\\n\",\"description\":\"replace greeting\"}\n```",
		"Changed files:\n- README.md\nVerification: inspected diff\nConfidence: medium",
	}
	implHits := 0
	implServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if implHits >= len(implReplies) {
			t.Fatalf("implementer received unexpected extra request")
		}

		reply := implReplies[implHits]
		implHits++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{"message": map[string]string{"content": reply}}},
		})
	}))

	defer implServer.Close()

	runner := &Runner{
		Client:            llama.NewClient(plannerServer.URL, 2*time.Second),
		ImplementerClient: llama.NewClient(implServer.URL, 2*time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxToolSteps: 3, MaxNoProgressTurns: 3},
	}

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "delegate"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	if answer != "Parent inspected child patch." {
		t.Fatalf("unexpected answer: %q", answer)
	}

	if plannerHits != len(plannerReplies) {
		t.Fatalf("planner hit count = %d, want %d", plannerHits, len(plannerReplies))
	}

	if implHits == 0 {
		t.Fatal("expected implementer client to receive child-task requests, got none")
	}
}

func TestRunWorkbranchChildTaskConvertsChildPanicToFailedTerminal(t *testing.T) {
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	var events []RunEvent
	runner := &Runner{
		Client: panicLLMClient{},
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		OnEvent: func(event RunEvent) {
			events = append(events, event)
		},
	}

	result := runner.runWorkbranchChildTask(
		context.Background(),
		workspace.ToolRequest{Tool: "task", Agent: "panic-child", Mode: "workbranch_write"},
		"change README greeting",
		llama.ChatOptions{},
	)
	if result.Summary != "Workbranch child task failed" {
		t.Fatalf("summary = %q, want failed child task", result.Summary)
	}
	if !strings.Contains(result.Error, "workbranch child task panic") || !strings.Contains(result.Error, "panic client invoked") {
		t.Fatalf("expected panic to be reported as child error, got %q", result.Error)
	}

	terminal := mustFindLifecycleRecord[autonomy.ChildTerminalRecord](t, events, childLifecycleTerminalEventRole)
	if terminal.Status != autonomy.ChildTerminalFailed || terminal.ResultKind != autonomy.ChildResultTypedBlocker {
		t.Fatalf("unexpected terminal after panic recovery: %#v", terminal)
	}

	acceptance := mustFindLifecycleRecord[autonomy.ChildAcceptanceRecord](t, events, childLifecycleAcceptanceEventRole)
	if acceptance.Decision != autonomy.ChildAcceptanceBlocked {
		t.Fatalf("panic terminal should be blocked, got %#v", acceptance)
	}
}

func TestRunnerReplaysFirstRepeatedToolRequestThenRejectsExactLoop(t *testing.T) {
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	replies := []string{
		"```tool\n{\"tool\":\"pwd\"}\n```",
		"```tool\n{\"tool\":\"pwd\"}\n```",
		"```tool\n{\"tool\":\"pwd\"}\n```",
		"Stopped after repeated loops.",
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests >= len(replies) {
			t.Fatalf("unexpected extra chat request")
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		replayedSummary string
		rejectedSummary string
		budgetEvent     string
	)

	runner := &Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  ".",
		}),
		Policy: RunPolicy{
			MaxToolSteps:       0,
			MaxNoProgressTurns: 2,
		},
		OnEvent: func(event RunEvent) {
			switch event.Role {
			case "budget_ledger":
				budgetEvent = event.Content
			}
		},
	}

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "read README.md"}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			if strings.Contains(strings.ToLower(event.Result.Summary), "replayed prior evidence") {
				replayedSummary = event.Result.Summary
			}

			if strings.Contains(event.Result.Summary, "Repeated tool request rejected") {
				rejectedSummary = event.Result.Summary
			}
		},
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	// DOOM_LOOP guard (threshold=3) trips on the third identical pwd call,
	// records the rejection, then forces a no-tools closeout so callers do
	// not receive an empty final answer.
	if requests < 3 {
		t.Fatalf("expected at least 3 model requests before doom-loop guard, got %d", requests)
	}

	if replayedSummary == "" {
		t.Fatal("expected second identical pwd to replay prior evidence before the guard trips")
	}

	_ = rejectedSummary
	_ = answer

	var ledger runnerBudgetLedger

	if err := json.Unmarshal([]byte(budgetEvent), &ledger); err != nil {
		t.Fatalf("decode budget ledger %q: %v", budgetEvent, err)
	}

	if ledger.StopReason != "doom_loop_guard" {
		t.Fatalf("expected stop_reason=doom_loop_guard, got %#v", ledger)
	}

	if answer != "Stopped after repeated loops." {
		t.Fatalf("expected forced closeout answer, got %q", answer)
	}

	if requests != 4 {
		t.Fatalf("expected three loop requests plus one forced closeout, got %d", requests)
	}
}

func TestRepeatedSearchFilesRejectsAfterReplayBeforeDoomLoop(t *testing.T) {
	root := t.TempDir()
	if err := writeTestFile(root, "internal/surfaces/tui/app/input.go", "package app\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	replies := []string{
		`{"tool":"search_files","pattern":"input","path":"."}`,
		`{"tool":"search_files","pattern":"input","path":"."}`,
		`{"tool":"search_files","pattern":"input","path":"."}`,
		"Stopped after exact search replay rejection.",
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests >= len(replies) {
			t.Fatalf("unexpected extra chat request")
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		replayed bool
		rejected bool
		events   []RunEvent
	)

	runner := &Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxNoProgressTurns: 8},
		OnEvent: func(event RunEvent) {
			events = append(events, event)
		},
	}

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "find input"}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			if event.Result.Tool == "search_files" && strings.Contains(strings.ToLower(event.Result.Summary), "replayed prior evidence") {
				replayed = true
			}

			if event.Result.Tool == "search_files" && strings.Contains(event.Result.Summary, "Repeated tool request rejected") {
				rejected = true
			}
		},
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	if !replayed {
		t.Fatal("expected the second exact search_files request to replay prior evidence")
	}

	if !rejected {
		t.Fatal("expected the third exact search_files request to reject the exhausted replay")
	}

	for _, event := range events {
		if event.Role == "doom_loop_guard" || strings.Contains(event.Content, "doom_loop_guard") {
			t.Fatalf("exact search replay exhaustion should reject before doom-loop approval path, events=%v", eventRolesFor(events))
		}
	}

	if answer != "Stopped after exact search replay rejection." {
		t.Fatalf("unexpected answer: %q", answer)
	}

	if requests != 4 {
		t.Fatalf("expected three tool requests plus final answer, got %d", requests)
	}
}

func TestReadOnlyDirectAnswerClosesAfterAnswerableExactSearchReplay(t *testing.T) {
	root := t.TempDir()
	docPath := "internal/documentviewer/document-viewer.go"

	if err := writeTestFile(root, docPath, strings.Join([]string{
		"package documentviewer",
		"",
		"const DocumentViewerBehavior = \"document viewer renders approved design documents\"",
	}, "\n")); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	replies := []string{
		fmt.Sprintf(`{"tool":"read_file","path":%q}`, docPath),
		`{"tool":"search_files","pattern":"*document*viewer*"}`,
		`{"tool":"search_files","pattern":"*document*viewer*"}`,
		"The file `internal/documentviewer/document-viewer.go` says the document viewer renders approved design documents. Confidence: high.",
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests >= len(replies) {
			t.Fatalf("unexpected extra chat request")
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		events   []RunEvent
		replayed bool
	)

	runner := &Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxNoProgressTurns: 8},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        "conversation",
			Contract:          "direct_answer",
			PermissionProfile: "read_only_workspace",
			Objective:         "What does internal/documentviewer/document-viewer.go say about the document viewer?",
			AllowedTools:      []string{"read_file", "search_files"},
		},
		OnEvent: func(event RunEvent) {
			events = append(events, event)
		},
	}

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "What does internal/documentviewer/document-viewer.go say about the document viewer?"}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			if event.Result.Tool == "search_files" && strings.Contains(strings.ToLower(event.Result.Summary), "replayed prior evidence") {
				replayed = true
			}
		},
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	if !replayed {
		t.Fatalf("expected exact search replay before model-owned final answer; events=%s", formatRunEventsForTest(events))
	}

	if requests != len(replies) {
		t.Fatalf("expected model-owned final answer after replayed evidence, used %d/%d requests; events=%s", requests, len(replies), formatRunEventsForTest(events))
	}

	if !strings.Contains(answer, docPath) ||
		!strings.Contains(strings.ToLower(answer), "document viewer") ||
		!strings.Contains(answer, "approved design documents") {

		t.Fatalf("model-owned answer should preserve the inspected document evidence, got:\n%s", answer)
	}

	for _, event := range events {
		if event.Role != "budget_ledger" {
			continue
		}

		var ledger runnerBudgetLedger

		if err := json.Unmarshal([]byte(event.Content), &ledger); err != nil {
			t.Fatalf("decode budget ledger %q: %v", event.Content, err)
		}

		if ledger.StopReason == "host_read_only_closeout" || ledger.StopReason == "read_only_prefetch_host_closeout" || ledger.StopReason == "read_only_replayed_evidence_closeout" {
			t.Fatalf("read-only replay must not use host/forced closeout, got %#v", ledger)
		}

		if ledger.RejectedActions != 0 {
			t.Fatalf("single replay before model final answer should not accumulate rejected actions, got %#v", ledger)
		}

		return
	}

	t.Fatalf("expected budget ledger; events=%s", formatRunEventsForTest(events))
}

func TestReadOnlyNoMatchProbeDoesNotForceCloseoutAfterSourceEvidence(t *testing.T) {
	root := t.TempDir()
	sourcePath := "internal/evidence/transcript/debuglog.go"

	if err := writeTestFile(root, sourcePath, strings.Join([]string{
		"package transcript",
		"",
		"const DebugLogModeRedacted = \"redacted\"",
		"const DebugLogModeFull = \"full\"",
	}, "\n")); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	replies := []string{
		fmt.Sprintf(`{"tool":"read_file","path":%q}`, sourcePath),
		`{"tool":"code_navigate","capability":"read_symbol","path":"internal/evidence/transcript/debuglog.go","pattern":"MissingDebugLogSymbol"}`,
		"The debug log source defines `DebugLogModeRedacted` and `DebugLogModeFull` in `internal/evidence/transcript/debuglog.go`; the follow-up symbol probe found no `MissingDebugLogSymbol`, so that missing symbol is not supported by the inspected code. Confidence: high.",
	}

	var requests int
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests >= len(replies) {
			t.Fatalf("unexpected extra chat request")
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))
	defer server.Close()

	var (
		events    []RunEvent
		noMatch   bool
		readCount int
	)

	runner := &Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxNoProgressTurns: 8},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        "conversation",
			Contract:          "direct_answer",
			PermissionProfile: "read_only_workspace",
			Objective:         "What does the debug log source say about redacted mode, and is MissingDebugLogSymbol present?",
			AllowedTools:      []string{"read_file", "code_navigate"},
		},
		PreExecute: func(step int, req workspace.ToolRequest) *workspace.ToolResult {
			if req.Tool != workspace.ToolNameCodeNavigate {
				return nil
			}

			noMatch = true

			return &workspace.ToolResult{
				Tool:    workspace.ToolNameCodeNavigate,
				Summary: "No generic code navigation matches for read_symbol",
				Output:  "capability: read_symbol\nroute_summary: no matches",
			}
		},
		OnEvent: func(event RunEvent) {
			events = append(events, event)
		},
	}

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "What does the debug log source say about redacted mode, and is MissingDebugLogSymbol present?"}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			if event.Result.Tool == workspace.ToolNameReadFile {
				readCount++
			}
		},
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	if !noMatch {
		t.Fatalf("expected no-match code_navigate probe; events=%s", formatRunEventsForTest(events))
	}

	if readCount != 1 {
		t.Fatalf("expected one executed source read, got %d", readCount)
	}

	if requests != len(replies) {
		t.Fatalf("expected model-owned final answer after no-match probe, used %d/%d requests; events=%s", requests, len(replies), formatRunEventsForTest(events))
	}

	if !strings.Contains(answer, "DebugLogModeRedacted") ||
		!strings.Contains(answer, "MissingDebugLogSymbol") ||
		!strings.Contains(answer, sourcePath) {

		t.Fatalf("model-owned answer should preserve source and no-match evidence, got:\n%s", answer)
	}

	for _, event := range events {
		if event.Role != "budget_ledger" {
			continue
		}

		var ledger runnerBudgetLedger
		if err := json.Unmarshal([]byte(event.Content), &ledger); err != nil {
			t.Fatalf("decode budget ledger %q: %v", event.Content, err)
		}

		if ledger.StopReason == "read_only_no_match_closeout" ||
			ledger.StopReason == "host_read_only_closeout" ||
			ledger.StopReason == "read_only_prefetch_host_closeout" {

			t.Fatalf("read-only no-match must not use host/forced closeout, got %#v", ledger)
		}

		return
	}

	t.Fatalf("expected budget ledger; events=%s", formatRunEventsForTest(events))
}

func TestRunnerRepeatedBroadInspectionStillHitsExploreGuard(t *testing.T) {
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	replies := []string{
		"```tool\n{\"tool\":\"list_files\"}\n```",
		"```tool\n{\"tool\":\"list_files\"}\n```",
		"Stopped after broad-inspection guard.",
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests >= len(replies) {
			t.Fatalf("unexpected extra chat request")
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	mgr := workspace.NewManager(config.Workspace{Root: root, CWD: root})
	if err := mgr.SetMode(workspace.ModeExplore); err != nil {
		t.Fatalf("set explore mode: %v", err)
	}

	runner := &Runner{
		Client:    llama.NewClient(server.URL, time.Second),
		Workspace: mgr,
		Policy: RunPolicy{
			MaxToolSteps:       0,
			MaxNoProgressTurns: 4,
		},
	}

	var (
		broadGuarded bool
		replayed     bool
	)

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "explore the repo"}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			if strings.Contains(event.Result.Summary, "Additional broad inspection rejected") {
				broadGuarded = true
			}

			if strings.Contains(strings.ToLower(event.Result.Summary), "replayed prior evidence") {
				replayed = true
			}
		},
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	if answer != "Stopped after broad-inspection guard." {
		t.Fatalf("unexpected answer %q", answer)
	}

	if !broadGuarded {
		t.Fatal("expected repeated broad inspection to hit the explore guard")
	}

	if replayed {
		t.Fatal("repeated broad inspection must not bypass explore guard through replay")
	}
}

func TestRunnerEmitsRecoveryNudgeBeforeGivingUpOnRepeatedBroadInspection(t *testing.T) {
	root := t.TempDir()
	if err := writeTestFile(root, "internal/surfaces/tui/app/app.go", "package app\n"); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	replies := []string{
		`{"tool":"list_files","path":".","recursive":true}`,
		`{"tool":"list_files","path":".","recursive":true}`,
		`{"tool":"list_files","path":".","recursive":true}`,
		"Answered from prior evidence after nudge.",
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests >= len(replies) {
			t.Fatalf("unexpected extra chat request (%d)", requests)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	mgr := workspace.NewManager(config.Workspace{Root: root, CWD: root})
	if err := mgr.SetMode(workspace.ModeExplore); err != nil {
		t.Fatalf("set explore mode: %v", err)
	}

	runner := &Runner{
		Client:    llama.NewClient(server.URL, time.Second),
		Workspace: mgr,
		Policy: RunPolicy{
			MaxToolSteps:       0,
			MaxNoProgressTurns: 6,
		},
	}

	var stopReason string

	runner.OnEvent = func(event RunEvent) {
		if event.Role == "budget_ledger" {
			var ledger runnerBudgetLedger

			if err := json.Unmarshal([]byte(event.Content), &ledger); err == nil {
				stopReason = ledger.StopReason
			}
		}
	}

	answer, err := runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "identify small refactor opportunities"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}

	// DOOM_LOOP guard (threshold=3) catches the third identical list_files
	// call before the rejection_recovery_nudge path is reached, then forces
	// a no-tools closeout.
	if stopReason != "doom_loop_guard" {
		t.Fatalf("expected stop_reason=doom_loop_guard, got %q", stopReason)
	}

	if answer != "Answered from prior evidence after nudge." {
		t.Fatalf("expected forced closeout answer, got %q", answer)
	}

	if requests != 4 {
		t.Fatalf("expected three loop requests plus one forced closeout, got %d", requests)
	}
}

