func TestDelegatedClosureEvidencePathsPreserveDiscoveryPacketOrderAmongEqualPriorityFiles(t *testing.T) {
	results := []workspace.ToolResult{{
		Tool:    "discovery_query",
		Summary: "Ran architecture_boundary discovery query",
		Output:  `{"artifact_path":".idiom/discovery/queries/query.json","evidence":[{"name":"text_anchor_search","summary":"Found handoff files","output_excerpt":"internal/runtime/agent/runner_core.go:574: result := r.runChildTask(ctx, req, opts)\ninternal/runtime/agent/implementation_flow.go:16: func (r *Runner) runChildTask(ctx context.Context, req workspace.ToolRequest, opts llama.ChatOptions) string\ninternal/runtime/agent/implementation_flow.go:18: func (AnswerComposer) Compose(input AnswerComposerInput) (string, bool)"}]}`,
	}}
	paths := delegatedClosureEvidencePaths("Explain how this harness uses subagents.", results, 4)

	if len(paths) < 2 {
		t.Fatalf("expected multiple closure evidence paths, got %#v", paths)
	}

	if paths[0] != "internal/runtime/agent/implementation_flow.go" || paths[1] != "internal/runtime/agent/runner_core.go" {
		t.Fatalf("expected discovery-ranked runner paths to stay ahead of ancillary files, got %#v", paths)
	}
}

func TestDelegatedReadOnlyDiminishingReturnsNudgeEscalates(t *testing.T) {
	results := []workspace.ToolResult{{
		Tool:    "discovery_query",
		Summary: "Ran architecture_boundary discovery query",
		Output:  `{"artifact_path":".idiom/discovery/queries/query.json","evidence":[{"name":"go_read_symbol","summary":"Read subagent flow","output_excerpt":"internal/runtime/agent/runner_core.go:648 runChildTask\ninternal/runtime/agent/implementation_flow.go:16 runChildTask"}]}`,
	}}
	first := delegatedReadOnlyDiminishingReturnsNudge("Explain how this harness uses subagents.", results, 1)
	second := delegatedReadOnlyDiminishingReturnsNudge("Explain how this harness uses subagents.", results, 2)

	if !strings.Contains(first, "The evidence ledger already supports a final answer") {
		t.Fatalf("expected first diminishing-returns nudge to cite ledger readiness, got:\n%s", first)
	}

	if !strings.Contains(first, "`internal/runtime/agent/runner_core.go`") {
		t.Fatalf("expected first diminishing-returns nudge to surface inspected paths, got:\n%s", first)
	}

	if !strings.Contains(second, "exact material missing claim") {
		t.Fatalf("expected second diminishing-returns nudge to require a concrete missing claim, got:\n%s", second)
	}

	if strings.Contains(strings.ToLower(first), "disables tools") ||
		strings.Contains(strings.ToLower(second), "disables tools") ||
		strings.Contains(first, "Post-readiness probes used") ||
		strings.Contains(second, "Post-readiness probes used") {
		t.Fatalf("diminishing-returns nudge should stay advisory, got:\n%s\n---\n%s", first, second)
	}
}

func TestDelegatedReadOnlyReadRedirectUsesPriorSearchHitWindow(t *testing.T) {
	runner := &Runner{
		AgentName: "child:explorer",
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily: "delegated_read_only",
			Objective:  "Explain how delegated child runners are created.\nKey terms: subagent, delegate, task",
		},
	}
	results := []workspace.ToolResult{
		{
			Tool:   "search_content",
			Output: "internal/runtime/agent/runner_core.go:574:\t\tresult := r.runChildTask(ctx, req, opts)\n",
		},
	}
	decision := runner.applyLanePreflight(runnerLanePreflightInput{
		Request: workspace.ToolRequest{Tool: "read_file", Path: "internal/runtime/agent/runner_core.go", StartLine: 9, EndLine: 109},
		Results: results,
	})

	if decision.Request.Tool != "read_file" || decision.Request.Path != "internal/runtime/agent/runner_core.go" {
		t.Fatalf("expected redirected hit-window read on runner.go, got %#v", decision.Request)
	}

	if decision.Request.StartLine != 554 || decision.Request.EndLine != 654 {
		t.Fatalf("expected redirected hit-window range, got %#v", decision.Request)
	}
}

