func TestFinalAnswerAcceptanceRetryPolicyRequiresToolsAndNoMutation(t *testing.T) {
	noToolsRunner := &Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        string(autonomy.TaskFamilyDirectAnswer),
			Contract:          string(workerruntime.ContractDirectAnswer),
			PermissionProfile: "read_only_workspace",
		},
	}
	if noToolsRunner.retryableFinalAnswerAcceptanceRejection(finalAnswerAcceptance{
		ContractAssessment: turnContractAssessment{}.withDiagnostic(turnDiagnostic{Kind: turnDiagnosticObjectiveRelevance}),
	}, nil, 0, nil) {
		t.Fatal("answer_objective_unmet must not enter retry policy")
	}

	readOnlyRunner := &Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        string(autonomy.TaskFamilyDirectAnswer),
			Contract:          string(workerruntime.ContractDirectAnswer),
			PermissionProfile: "read_only_workspace",
			AllowedTools:      []string{"read_file"},
		},
	}
	if !readOnlyRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationSourceGroundingUnmet), nil, 1, nil) {
		t.Fatal("source_grounding_unmet should remain retryable before the retry limit is exhausted")
	}

	if !readOnlyRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationSourceGroundingUnmet), nil, 2, nil) {
		t.Fatal("source_grounding_unmet must remain retryable when prior rejections (2) are within the read-only retry budget (3)")
	}

	if !readOnlyRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationSourceGroundingUnmet), nil, 3, nil) {
		t.Fatal("source_grounding_unmet must remain retryable for the first source-evidence recovery extension")
	}

	if !readOnlyRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationSourceGroundingUnmet), nil, 4, nil) {
		t.Fatal("source_grounding_unmet must remain retryable for the second source-evidence recovery extension")
	}

	if readOnlyRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationSourceGroundingUnmet), nil, 5, nil) {
		t.Fatal("source_grounding_unmet must become terminal once the bounded source-evidence recovery budget is exhausted")
	}

	noReadToolRunner := &Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        string(autonomy.TaskFamilyDirectAnswer),
			Contract:          string(workerruntime.ContractDirectAnswer),
			PermissionProfile: "read_only_workspace",
			AllowedTools:      []string{"search_content"},
		},
	}
	if noReadToolRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationSourceGroundingUnmet), nil, 3, nil) {
		t.Fatal("source_grounding_unmet must not get extra read-recovery retries when no source-body read tool is available")
	}

	architectureRunner := &Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        string(autonomy.TaskFamilyArchitecture),
			Contract:          string(workerruntime.ContractArchitecture),
			PermissionProfile: "read_only_workspace",
			AllowedTools:      []string{"read_file", "context_query"},
		},
	}
	if !architectureRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationNonAnswerProse, turnReasonInsufficientEvidenceAnswer), nil, 0, nil) {
		t.Fatal("read-only architecture insufficient-evidence non-answer should get a recovery turn")
	}

	if architectureRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationNonAnswerProse, turnReasonNonAnswerProse), nil, 0, nil) {
		t.Fatal("generic architecture non-answer prose should remain terminal")
	}

	malformedRequiredPathRunner := &Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        string(autonomy.TaskFamilyDirectAnswer),
			Contract:          string(workerruntime.ContractDirectAnswer),
			PermissionProfile: "read_only_workspace",
			RequiredEditPaths: []string{"internal/surfaces/tui/app/model.go"},
			AllowedTools:      []string{"read_file"},
		},
	}
	if malformedRequiredPathRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationSourceGroundingUnmet), nil, 0, nil) {
		t.Fatal("required_edit_paths must keep malformed direct-answer/read-only briefs out of final-answer retry policy")
	}

	mutationRunner := &Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        string(autonomy.TaskFamilyImplementation),
			Contract:          "implementation_result",
			PermissionProfile: "guarded_workspace_write",
			RequiredEditPaths: []string{"internal/surfaces/tui/app/model.go"},
			AllowedTools:      []string{"read_file", "apply_patch"},
		},
	}
	if mutationRunner.retryableFinalAnswerAcceptanceRejection(rejectedFinalAnswerAcceptanceForTest(turnViolationRequiredEditPathsRemaining), nil, 0, nil) {
		t.Fatal("mutation required_edit_paths_remaining must not enter read-only final-answer retry policy")
	}

	if mutationRunner.retryableFinalAnswerAcceptanceRejection(finalAnswerAcceptance{
		ContractAssessment: turnContractAssessment{}.withDiagnostic(turnDiagnostic{Kind: turnDiagnosticObjectiveRelevance}),
	}, nil, 0, nil) {
		t.Fatal("objective relevance advisory must not enter mutation retry policy")
	}
}

func TestEmitAcceptedAnswerSignalsImplementationEvidenceUsesChangedPaths(t *testing.T) {
	runner := &Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			Lane:              "implement",
			Contract:          "implementation_result",
			TaskFamily:        "implementation",
			PermissionProfile: "guarded_workspace_write",
			Objective:         "Update TDD obligation planning.",
		},
	}

	var readiness map[string]any

	runner.OnEvent = func(event RunEvent) {
		if event.Role != "readiness_check" {
			return
		}

		_ = json.Unmarshal([]byte(event.Content), &readiness)
	}
	runner.emitAcceptedAnswerSignals(
		"Changed `internal/workflows/productworkflow/tdd_obligation_plans.go` and tests.",
		[]workspace.ToolResult{
			{
				Tool:    "read_file",
				Summary: "Read f2 internal/workflows/productworkflow/tdd_obligation_plans_test.go lines 1-220",
				Output:  "RelPath: \"adrs/ADR-1.md\"\nFile: \"adrs/prd.md\"\nOwner: \"adrs/greeting.test.js\"",
			},
			{
				Tool:    "edit_file",
				Summary: "Edited internal/workflows/productworkflow/tdd_obligation_plans.go",
			},
			{
				Tool:    "edit_file",
				Summary: "Edited internal/workflows/productworkflow/tdd_obligation_plans_test.go",
			},
		},
	)

	rawPaths, _ := readiness["evidence_paths"].([]any)
	got := make([]string, 0, len(rawPaths))

	for _, raw := range rawPaths {
		if value, ok := raw.(string); ok {
			got = append(got, value)
		}
	}

	for _, want := range []string{"internal/workflows/productworkflow/tdd_obligation_plans.go", "internal/workflows/productworkflow/tdd_obligation_plans_test.go"} {
		if !slices.Contains(got, want) {
			t.Fatalf("expected implementation readiness paths to contain changed path %q, got %#v", want, got)
		}
	}

	for _, forbidden := range []string{"adrs/ADR-1.md", "adrs/prd.md", "adrs/greeting.test.js"} {
		if slices.Contains(got, forbidden) {
			t.Fatalf("did not expect fixture path %q in implementation readiness evidence, got %#v", forbidden, got)
		}
	}
}

