func TestPlanExecuteFailureFeedbackUsesRunStateTransportAfterNativeFallback(t *testing.T) {
	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "main",
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "implementation_result",
		PermissionProfile: "guarded_workspace_write",
		AllowedTools:      []string{workspace.ToolNameSubmitPlan},
		RequiredEditPaths: []string{"a.go"},
	}
	sourceReady := workspace.ToolResult{Tool: "read_file", Summary: "Read f1 a.go lines 1-10 (total lines: 10)", Output: "1:package a\n"}
	results := []workspace.ToolResult{sourceReady}
	runState := &runnerRunState{
		collectedResults:                        append([]workspace.ToolResult(nil), results...),
		currentAllowedTools:                     []string{workspace.ToolNameSubmitPlan},
		planThenExecuteNativeSubmitPlanDisabled: true,
	}

	var nextAction runnerNextActionState
	var failure runnerFailureFeedbackPacket
	runner := &Runner{
		Client:              llama.NewClient("http://example.invalid", time.Second).WithBackend(config.BackendLlama),
		AgentName:           "main",
		RuntimeBrief:        brief,
		currentAllowedTools: []string{workspace.ToolNameSubmitPlan},
		OnEvent: func(event RunEvent) {
			switch event.Role {
			case "next_action_state":
				if err := json.Unmarshal([]byte(event.Content), &nextAction); err != nil {
					t.Fatalf("unmarshal next_action_state: %v\n%s", err, event.Content)
				}
			case "failure_feedback":
				if err := json.Unmarshal([]byte(event.Content), &failure); err != nil {
					t.Fatalf("unmarshal failure_feedback: %v\n%s", err, event.Content)
				}
			}
		},
	}
	collectedResults := append([]workspace.ToolResult(nil), results...)
	messages := []llama.ChatMessage{}
	recorder := runnerTurnRecorder{
		runner:           runner,
		runState:         runState,
		collectedResults: &collectedResults,
		turnMessages:     &messages,
	}
	rejected := workspace.ToolResult{
		Tool:    workspace.ToolNameSubmitPlan,
		Summary: "submit_plan rejected after textual fallback",
		Error:   "submit_plan JSON object required",
	}

	recorder.recordWithOptions(2, workspace.ToolRequest{Tool: workspace.ToolNameSubmitPlan}, rejected, "tool_rejected", runnerRecordOptions{})

	if nextAction.RecoveryState == nil {
		t.Fatalf("missing recovery state in next-action event")
	}
	if nextAction.RecoveryState.PhaseID != turnPhaseSubmitReadyTextual {
		t.Fatalf("next-action phase = %q, want textual fallback phase %q", nextAction.RecoveryState.PhaseID, turnPhaseSubmitReadyTextual)
	}
	if strings.Contains(nextAction.RecoveryState.RecoveryCardProtocolProjectionID, turnPhaseSubmitReadyNativeRequired) {
		t.Fatalf("next-action recovery state leaked native projection after fallback: %#v", nextAction.RecoveryState)
	}
	if !strings.Contains(failure.RecoveryCard, turnPhaseSubmitReadyTextual) {
		t.Fatalf("failure feedback should use textual fallback projection, got:\n%s", failure.RecoveryCard)
	}
	if strings.Contains(failure.RecoveryCard, turnPhaseSubmitReadyNativeRequired) {
		t.Fatalf("failure feedback leaked native projection after fallback:\n%s", failure.RecoveryCard)
	}
}

func TestPlanExecuteAnchorRefreshAutonomyRecoveryCardAdvertisesDerivedReadTools(t *testing.T) {
	var events []RunEvent

	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "main",
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "implementation_result",
		PermissionProfile: "guarded_workspace_write",
		RequiredEditPaths: []string{"native/src/simulation/production/production_execution.cpp"},
	}
	rejected := workspace.ToolResult{
		Tool:    "submit_plan",
		Summary: "submit_plan rejected: required edit path coverage mismatch",
		Error:   "invalid edit anchor(s): `native/src/simulation/production/production_execution.cpp: old_text not found in current source`.",
	}
	results := []workspace.ToolResult{
		{Tool: "read_file", Summary: "Read f5 native/src/simulation/production/production_execution.cpp lines 1-180 (total lines: 1593)"},
		rejected,
	}
	runner := &Runner{
		AgentName:           "main",
		RuntimeBrief:        brief,
		currentAllowedTools: []string{"submit_plan"},
		OnEvent: func(event RunEvent) {
			events = append(events, event)
		},
	}

	runner.activeAutonomy = newRunnerAutonomyRecorder(runner, RunPolicy{}, brief, results)

	if runner.activeAutonomy == nil {
		t.Fatal("expected autonomy recorder")
	}

	runner.emitNextActionState(2, "tool_result", workspace.ToolRequest{Tool: "submit_plan"}, rejected, results, false)

	autonomyEvents := decodeRunnerAutonomyEventsForTest(t, events)
	for _, event := range autonomyEvents {
		if event.Lifecycle == nil {
			continue
		}

		for _, surface := range event.Lifecycle.SurfaceSummaries {
			if surface.SurfaceID != "recovery_card" {
				continue
			}

			if !slices.Contains(surface.CallableTools, "read_file") ||
				!slices.Contains(surface.CallableTools, "code_navigate") ||
				slices.Contains(surface.CallableTools, "submit_plan") {

				t.Fatalf("autonomy recovery card callable tools = %#v, want read_file/code_navigate only", surface.CallableTools)
			}

			if surface.RecoveryID == "" ||
				surface.RecoveryProjectionID == "" ||
				!slices.Contains(surface.SafeAlternatives, actionRead) {

				t.Fatalf("autonomy recovery card should carry typed recovery state fields: %#v", surface)
			}

			return
		}
	}

	t.Fatalf("expected autonomy recovery_card surface, events=%#v", autonomyEvents)
}

func assertRecoveryCardEvent(t *testing.T, events []RunEvent, invariantID string, summary string) {
	t.Helper()

	cardsByRole := recoveryCardsByRole(t, events)

	var cards []string

	for _, roleCards := range cardsByRole {
		cards = append(cards, roleCards...)
	}

	for _, card := range cards {
		if strings.Contains(card, invariantID) && strings.Contains(card, summary) {
			assertRecoveryCardOmitsProjectWorkflowTerms(t, card)

			return
		}
	}

	t.Fatalf("expected emitted recovery card with invariant %q and summary %q, cards=%#v roles=%v", invariantID, summary, cards, eventRolesFor(events))
}

func assertRecoveryCardRole(t *testing.T, events []RunEvent, role string, wants ...string) {
	t.Helper()

	cardsByRole := recoveryCardsByRole(t, events)
	for _, card := range cardsByRole[role] {
		matches := true

		for _, want := range wants {
			if !strings.Contains(card, want) {
				matches = false
				break
			}
		}

		if matches {
			assertRecoveryCardOmitsProjectWorkflowTerms(t, card)

			return
		}
	}

	t.Fatalf("expected %s recovery card containing %#v, cards=%#v roles=%v", role, wants, cardsByRole[role], eventRolesFor(events))
}

func recoveryCardsByRole(t *testing.T, events []RunEvent) map[string][]string {
	t.Helper()

	cards := make(map[string][]string)

	for _, event := range events {
		switch event.Role {
		case "next_action_state":
			var state runnerNextActionState

			if err := json.Unmarshal([]byte(event.Content), &state); err == nil && strings.TrimSpace(state.RecoveryCard) != "" {
				cards[event.Role] = append(cards[event.Role], state.RecoveryCard)
			}
		case "failure_feedback":
			var packet runnerFailureFeedbackPacket

			if err := json.Unmarshal([]byte(event.Content), &packet); err == nil && strings.TrimSpace(packet.RecoveryCard) != "" {
				cards[event.Role] = append(cards[event.Role], packet.RecoveryCard)
			}
		}
	}

	return cards
}

