func TestSourceVerificationDoesNotTreatIncidentalPathMentionAsVerificationException(t *testing.T) {
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:           "implementation",
		VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
	}
	results := []workspace.ToolResult{
		{
			Tool:   "read_file",
			Output: "Implement the feature by changing pkg/feature.go and pkg/feature_test.go.",
		},
		{Tool: "edit_file", Summary: "Edited pkg/feature.go"},
		{Tool: "shell", Summary: "git diff --check passed", Output: "git diff --check passed"},
	}

	if summary, errorText, reject := sourceEditVerificationRejection(workspace.ToolRequest{
		Tool: "read_file",
		Path: "pkg/feature_test.go",
	}, brief, results); !reject {
		t.Fatal("incidental source text should not become a verification-phase read exception")
	} else if !strings.Contains(summary, "Source edit verification required") || !strings.Contains(errorText, "source edits are present") {
		t.Fatalf("unexpected verification rejection: %q %q", summary, errorText)
	}
}

func TestVerifiedSourceCloseoutIgnoresIncidentalPathMentions(t *testing.T) {
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:           "implementation",
		VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
	}
	results := []workspace.ToolResult{
		{
			Tool:   "read_file",
			Output: "Implement the feature by changing pkg/feature.go and pkg/feature_test.go.",
		},
		{Tool: "edit_file", Summary: "Edited pkg/feature.go"},
		{Tool: "shell", Summary: "Ran shell command", Output: "$ cargo check\nFinished dev profile"},
	}

	if prompt, ok := sourceEditCloseoutPrompt(workspace.ToolRequest{
		Tool: "read_file",
		Path: "pkg/feature_test.go",
	}, brief, results); !ok {
		t.Fatal("verified source closeout should not be blocked by incidental path mentions")
	} else if !strings.Contains(prompt, "Successful source edits") {
		t.Fatalf("unexpected closeout prompt:\n%s", prompt)
	}
}

func TestStateStoreTracksRemainingRequiredEdits(t *testing.T) {
	store := newStateStore(nil, false, 0)
	store.SetRequiredEditPaths([]string{
		"./internal/runtime/agent/runner_core.go",
		"internal\\runtime\\agent\\evidence_readonly.go",
		"internal/runtime/agent/runner_core.go",
	})

	store.TrackWritePath("internal/runtime/agent/runner_core.go")

	got := store.RequiredEditsRemaining()
	want := []string{"internal/runtime/agent/evidence_readonly.go"}
	if len(got) != len(want) || got[0] != want[0] {
		t.Fatalf("remaining required edits = %#v, want %#v", got, want)
	}

	decision := store.WriteDecision("implementation.required_paths")
	if decision.Allowed || len(decision.PendingRequiredPaths()) != 1 {
		t.Fatalf("write decision should expose pending required path: %#v", decision)
	}
}

func TestStateStoreAllowedToolsAreCopySafe(t *testing.T) {
	store := newStateStore(nil, false, 0)
	tools := []string{"read_file", "search_content"}
	store.SetAllowedTools(tools)
	tools[0] = "shell"

	got := store.AllowedTools()
	got[1] = "apply_patch"

	again := store.AllowedTools()
	if again[0] != "read_file" || again[1] != "search_content" {
		t.Fatalf("allowed tools mutated through caller slice: %#v", again)
	}
}

func TestStateStoreTracksFingerprints(t *testing.T) {
	store := newStateStore(nil, false, 0)
	fp := store.ComputeFingerprint(workspace.ToolRequest{Tool: "read_file", Path: "README.md"})
	store.TrackFingerprint(fp, workspace.ToolResult{Tool: "read_file", Summary: "ok"})

	impl, ok := store.(*stateStore)
	if !ok {
		t.Fatalf("newStateStore returned %T, want *stateStore", store)
	}
	if got := impl.fingerprints[fp].Summary; got != "ok" {
		t.Fatalf("tracked fingerprint summary = %q, want ok", got)
	}
}

func TestRunnerSetCurrentAllowedToolsSyncsStateStore(t *testing.T) {
	runner := &Runner{StateStore: newStateStore(nil, false, 0)}
	state := &runnerRunState{}

	runner.setCurrentAllowedTools(state, []string{"read_file", "submit_plan"})

	if got := runner.StateStore.AllowedTools(); len(got) != 2 || got[0] != "read_file" || got[1] != "submit_plan" {
		t.Fatalf("StateStore allowed tools = %#v", got)
	}
	if got := state.currentAllowedTools; len(got) != 2 || got[0] != "read_file" || got[1] != "submit_plan" {
		t.Fatalf("run state allowed tools = %#v", got)
	}
}

func TestRunnerLoopTurnStatePrefersStateStoreChangedPaths(t *testing.T) {
	store := newStateStore(nil, false, 0)
	store.TrackWritePath("docs/design.md")
	runner := &Runner{StateStore: store}
	state := &runnerRunState{
		stepNumber:          3,
		currentAllowedTools: []string{"submit_plan"},
	}

	got := runner.loopTurnState(state)
	if got.Step != 3 || len(got.AllowedTools) != 1 || got.AllowedTools[0] != "submit_plan" {
		t.Fatalf("unexpected loop turn state surface: %#v", got)
	}
	if len(got.ChangedPaths) != 1 || got.ChangedPaths[0] != "docs/design.md" {
		t.Fatalf("loop turn state changed paths = %#v, want docs/design.md", got.ChangedPaths)
	}
}
